using Godot;
using System;
using System.Collections.Generic;

namespace ApexGP24;

public struct TrackSample
{
    public Vector3 Center;
    public Vector3 Forward;
    public Vector3 Right;
    public float Distance;
    public float Curvature;
}

public partial class TrackBuilder3D : Node3D
{
    public const float TrackHalfWidth = 7.2f;
    public const float KerbWidth = 0.95f;
    public const float RunoffWidth = 7.5f;
    public const float BarrierOffset = TrackHalfWidth + KerbWidth + RunoffWidth;

    public List<TrackSample> Samples { get; } = new();
    public float TotalLength { get; private set; } = 1.0f;

    public void BuildCircuit()
    {
        GenerateSplineSamples();
        BuildGroundPlane();
        BuildTrackMeshes();
        BuildStartGantry();
        BuildGrandstandsAndTrees();
    }

    private void GenerateSplineSamples()
    {
        // Real closed GP circuit loop (~1.65 km smooth FIA flow: long main straight, T1 hairpin, fast esses, sweeping back straight, final chicane)
        Vector3[] controlPts =
        {
            new Vector3(0f, 0.0f, 0f),
            new Vector3(0f, 0.2f, -150f),
            new Vector3(12f, 1.8f, -280f),
            new Vector3(72f, 3.6f, -335f),
            new Vector3(145f, 4.2f, -310f),
            new Vector3(188f, 2.4f, -225f),
            new Vector3(165f, 1.0f, -135f),
            new Vector3(230f, 2.5f, -55f),
            new Vector3(268f, 3.8f, 55f),
            new Vector3(235f, 2.6f, 170f),
            new Vector3(140f, 1.2f, 225f),
            new Vector3(45f, 0.6f, 200f),
            new Vector3(2f, 0.0f, 118f)
        };

        var rawPts = new List<Vector3>();
        int n = controlPts.Length;
        const int subDiv = 28;

        for (int i = 0; i < n; i++)
        {
            Vector3 p0 = controlPts[(i - 1 + n) % n];
            Vector3 p1 = controlPts[i];
            Vector3 p2 = controlPts[(i + 1) % n];
            Vector3 p3 = controlPts[(i + 2) % n];

            for (int s = 0; s < subDiv; s++)
            {
                float t = s / (float)subDiv;
                rawPts.Add(CatmullRom(p0, p1, p2, p3, t));
            }
        }

        Samples.Clear();
        float accDist = 0f;
        int count = rawPts.Count;

        for (int i = 0; i < count; i++)
        {
            Vector3 prev = rawPts[(i - 1 + count) % count];
            Vector3 curr = rawPts[i];
            Vector3 next = rawPts[(i + 1) % count];

            if (i > 0) accDist += curr.DistanceTo(prev);

            Vector3 fwd = (next - prev).Normalized();
            Vector3 right = fwd.Cross(Vector3.Up).Normalized();
            Vector3 v1 = (curr - prev).Normalized();
            Vector3 v2 = (next - curr).Normalized();
            float crossY = v1.X * v2.Z - v1.Z * v2.X;
            float segLen = Mathf.Max(0.1f, curr.DistanceTo(prev));

            Samples.Add(new TrackSample
            {
                Center = curr,
                Forward = fwd,
                Right = right,
                Distance = accDist,
                Curvature = crossY / segLen
            });
        }

        TotalLength = accDist + rawPts[0].DistanceTo(rawPts[count - 1]);
    }

    private static Vector3 CatmullRom(Vector3 p0, Vector3 p1, Vector3 p2, Vector3 p3, float t)
    {
        float t2 = t * t;
        float t3 = t2 * t;
        return 0.5f * (
            (2.0f * p1) +
            (-p0 + p2) * t +
            (2.0f * p0 - 5.0f * p1 + 4.0f * p2 - p3) * t2 +
            (-p0 + 3.0f * p1 - 3.0f * p2 + p3) * t3
        );
    }

    public TrackSample SampleAtDistance(float dist)
    {
        float wrapped = ((dist % TotalLength) + TotalLength) % TotalLength;
        int count = Samples.Count;
        int lo = 0;
        int hi = count - 1;
        while (lo + 1 < hi)
        {
            int mid = (lo + hi) >> 1;
            if (Samples[mid].Distance <= wrapped) lo = mid;
            else hi = mid;
        }

        int i0 = lo;
        int i1 = (lo + 1) % count;
        float d0 = Samples[i0].Distance;
        float d1 = i1 == 0 ? TotalLength : Samples[i1].Distance;
        float span = Mathf.Max(0.001f, d1 - d0);
        float frac = Mathf.Clamp((wrapped - d0) / span, 0f, 1f);

        TrackSample a = Samples[i0];
        TrackSample b = Samples[i1];
        Vector3 fwd = a.Forward.Lerp(b.Forward, frac).Normalized();
        return new TrackSample
        {
            Center = a.Center.Lerp(b.Center, frac),
            Forward = fwd,
            Right = fwd.Cross(Vector3.Up).Normalized(),
            Distance = wrapped,
            Curvature = Mathf.Lerp(a.Curvature, b.Curvature, frac)
        };
    }

    private void BuildGroundPlane()
    {
        var plane = new MeshInstance3D
        {
            Mesh = new PlaneMesh { Size = new Vector2(1600f, 1600f) },
            Position = new Vector3(110f, -0.35f, -50f),
            MaterialOverride = new StandardMaterial3D
            {
                AlbedoColor = new Color(0.14f, 0.30f, 0.13f),
                Roughness = 0.95f
            }
        };
        AddChild(plane);
    }

    private void BuildTrackMeshes()
    {
        var roadSt = new SurfaceTool();
        roadSt.Begin(Mesh.PrimitiveType.Triangles);

        var detailSt = new SurfaceTool();
        detailSt.Begin(Mesh.PrimitiveType.Triangles);

        int count = Samples.Count;
        for (int i = 0; i < count; i++)
        {
            TrackSample a = Samples[i];
            TrackSample b = Samples[(i + 1) % count];
            float vA = a.Distance * 0.10f;
            float vB = (i == count - 1 ? TotalLength : b.Distance) * 0.10f;

            // 1. Main Asphalt Surface (Textured)
            Vector3 rLA = a.Center - a.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            Vector3 rRA = a.Center + a.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            Vector3 rLB = b.Center - b.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            Vector3 rRB = b.Center + b.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            AddUvQuad(roadSt, rLA, rRA, rRB, rLB, new Vector2(0, vA), new Vector2(1, vA), new Vector2(1, vB), new Vector2(0, vB));

            // 2. Red & White FIA Kerbs + Asphalt/Gravel Runoff + 3D Armco/TECPRO Barriers
            bool alt = ((int)(a.Distance / 3.8f) % 2) == 0;
            Color kerbCol = alt ? new Color(0.86f, 0.11f, 0.10f) : new Color(0.95f, 0.96f, 0.98f);
            Color runoffCol = alt ? new Color(0.17f, 0.34f, 0.20f) : new Color(0.15f, 0.31f, 0.18f);
            Color wallCol = ((int)(a.Distance / 9.0f) % 2 == 0)
                ? new Color(0.88f, 0.90f, 0.93f)
                : new Color(0.82f, 0.12f, 0.10f);

            foreach (float side in new[] { -1f, 1f })
            {
                Vector3 kInA = a.Center + a.Right * (side * TrackHalfWidth) + Vector3.Up * 0.05f;
                Vector3 kOutA = a.Center + a.Right * (side * (TrackHalfWidth + KerbWidth)) + Vector3.Up * 0.09f;
                Vector3 kInB = b.Center + b.Right * (side * TrackHalfWidth) + Vector3.Up * 0.05f;
                Vector3 kOutB = b.Center + b.Right * (side * (TrackHalfWidth + KerbWidth)) + Vector3.Up * 0.09f;

                Vector3 runOutA = a.Center + a.Right * (side * BarrierOffset) + Vector3.Up * 0.02f;
                Vector3 runOutB = b.Center + b.Right * (side * BarrierOffset) + Vector3.Up * 0.02f;

                Vector3 wBotA = runOutA;
                Vector3 wTopA = runOutA + Vector3.Up * 1.15f;
                Vector3 wBotB = runOutB;
                Vector3 wTopB = runOutB + Vector3.Up * 1.15f;

                if (side < 0)
                {
                    AddColorQuad(detailSt, kOutA, kInA, kInB, kOutB, kerbCol);
                    AddColorQuad(detailSt, runOutA, kOutA, kOutB, runOutB, runoffCol);
                    AddColorQuad(detailSt, wBotA, wBotB, wTopB, wTopA, wallCol);
                }
                else
                {
                    AddColorQuad(detailSt, kInA, kOutA, kOutB, kInB, kerbCol);
                    AddColorQuad(detailSt, kOutA, runOutA, runOutB, kOutB, runoffCol);
                    AddColorQuad(detailSt, wBotB, wBotA, wTopA, wTopB, wallCol);
                }
            }
        }

        roadSt.GenerateNormals();
        var roadMesh = new MeshInstance3D
        {
            Mesh = roadSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateAsphaltMaterial()
        };
        AddChild(roadMesh);

        detailSt.GenerateNormals();
        var detailMesh = new MeshInstance3D
        {
            Mesh = detailSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateVertexColorMaterial(0.75f, true)
        };
        AddChild(detailMesh);
    }

    private void BuildStartGantry()
    {
        TrackSample s0 = SampleAtDistance(0f);
        var gantry = new Node3D
        {
            Position = s0.Center,
            Basis = Basis.LookingAt(s0.Forward, Vector3.Up)
        };
        AddChild(gantry);

        var darkMetal = new StandardMaterial3D { AlbedoColor = new Color(0.11f, 0.14f, 0.19f), Metallic = 0.6f, Roughness = 0.35f };
        var bannerMat = new StandardMaterial3D { AlbedoColor = new Color(0.84f, 0.07f, 0.07f), Roughness = 0.35f };

        foreach (float side in new[] { -1f, 1f })
        {
            gantry.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(0.7f, 7.2f, 0.7f) },
                Position = new Vector3(side * (TrackHalfWidth + 1.8f), 3.6f, 0f),
                MaterialOverride = darkMetal
            });
        }

        gantry.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3((TrackHalfWidth + 2.2f) * 2f, 1.45f, 0.9f) },
            Position = new Vector3(0f, 6.7f, 0f),
            MaterialOverride = bannerMat
        });

        gantry.AddChild(new Label3D
        {
            Text = "APEX GP 24  •  START / FINISH",
            Position = new Vector3(0f, 6.7f, 0.50f),
            FontSize = 72,
            PixelSize = 0.0085f,
            Modulate = Colors.White
        });

        // White checkered start line strip on asphalt
        gantry.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(TrackHalfWidth * 1.92f, 0.02f, 1.2f) },
            Position = new Vector3(0f, 0.055f, 0f),
            MaterialOverride = new StandardMaterial3D { AlbedoColor = Colors.White, Roughness = 0.6f }
        });
    }

    private void BuildGrandstandsAndTrees()
    {
        var standMat = new StandardMaterial3D { AlbedoColor = new Color(0.22f, 0.25f, 0.31f), Roughness = 0.85f };
        var roofMat = new StandardMaterial3D { AlbedoColor = new Color(0.92f, 0.94f, 0.97f), Roughness = 0.45f };
        var crowdMat = new StandardMaterial3D { AlbedoColor = new Color(0.78f, 0.22f, 0.20f), Roughness = 0.90f };
        var trunkMat = new StandardMaterial3D { AlbedoColor = new Color(0.28f, 0.19f, 0.12f), Roughness = 0.95f };
        var leafMat = new StandardMaterial3D { AlbedoColor = new Color(0.14f, 0.38f, 0.16f), Roughness = 0.88f };

        for (float d = 25f; d < TotalLength - 30f; d += 85f)
        {
            TrackSample s = SampleAtDistance(d);
            float side = ((int)(d / 85f) % 2 == 0) ? -1f : 1f;

            var stand = new Node3D
            {
                Position = s.Center + s.Right * (side * (BarrierOffset + 8.5f)),
                Basis = Basis.LookingAt(s.Forward, Vector3.Up)
            };
            AddChild(stand);

            stand.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(9.0f, 5.2f, 34.0f) },
                Position = new Vector3(0f, 2.6f, 0f),
                MaterialOverride = standMat
            });
            stand.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(4.2f, 4.4f, 32.5f) },
                Position = new Vector3(-side * 2.7f, 2.8f, 0f),
                MaterialOverride = crowdMat
            });
            stand.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(11.5f, 0.45f, 35.5f) },
                Position = new Vector3(-side * 0.8f, 6.2f, 0f),
                MaterialOverride = roofMat
            });
        }

        // Trackside trees outside opposite barrier
        for (float d = 15f; d < TotalLength; d += 34f)
        {
            TrackSample s = SampleAtDistance(d);
            foreach (float side in new[] { -1f, 1f })
            {
                Vector3 pos = s.Center + s.Right * (side * (BarrierOffset + 16.0f + (d % 9f)));
                var tree = new Node3D { Position = pos };
                AddChild(tree);
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new CylinderMesh { TopRadius = 0.25f, BottomRadius = 0.35f, Height = 3.2f, RadialSegments = 8 },
                    Position = new Vector3(0f, 1.6f, 0f),
                    MaterialOverride = trunkMat
                });
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new SphereMesh { Radius = 2.6f, Height = 4.6f, RadialSegments = 10, Rings = 6 },
                    Position = new Vector3(0f, 4.3f, 0f),
                    MaterialOverride = leafMat
                });
            }
        }
    }

    private static void AddUvQuad(SurfaceTool st, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector2 uvA, Vector2 uvB, Vector2 uvC, Vector2 uvD)
    {
        st.SetUV(uvA); st.AddVertex(a);
        st.SetUV(uvB); st.AddVertex(b);
        st.SetUV(uvC); st.AddVertex(c);

        st.SetUV(uvA); st.AddVertex(a);
        st.SetUV(uvC); st.AddVertex(c);
        st.SetUV(uvD); st.AddVertex(d);
    }

    private static void AddColorQuad(SurfaceTool st, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Color col)
    {
        st.SetColor(col); st.AddVertex(a);
        st.SetColor(col); st.AddVertex(b);
        st.SetColor(col); st.AddVertex(c);

        st.SetColor(col); st.AddVertex(a);
        st.SetColor(col); st.AddVertex(c);
        st.SetColor(col); st.AddVertex(d);
    }
}

