using Godot;
using System;

namespace ApexGP24;

public partial class PlayerCar3D : Node3D
{
    private TrackBuilder3D _track;
    private Camera3D _cockpitCam;
    private Camera3D _tCam;
    private Node3D _wheelPivot;
    private Node3D _frontLeftWheel;
    private Node3D _frontRightWheel;
    private Label3D _mfdSpeedLabel;
    private Label3D _mfdGearLabel;
    private Label3D _mfdLapLabel;
    private Label3D _mfdOvertakeLabel;
    private MeshInstance3D _mfdOvertakeBar;
    private StandardMaterial3D _overtakeBarMat;

    public bool IsCockpitCamera { get; private set; } = true;
    public float TrackDistance { get; private set; } = 0f;
    public float LateralOffset { get; private set; } = 0f;
    public float HeadingOffset { get; private set; } = 0f;
    public float SpeedKmh { get; private set; } = 0f;
    public float SteerAngle { get; private set; } = 0f;
    public float ErsCharge { get; private set; } = 100f;
    public bool ErsEnabled { get; set; } = false;
    public int CurrentLap { get; private set; } = 1;
    public float CurrentLapTime { get; private set; } = 0f;
    public float BestLapTime { get; private set; } = 999f;

    public bool InputLeft { get; set; }
    public bool InputRight { get; set; }
    public bool InputGas { get; set; }
    public bool InputBrake { get; set; }

    private float _wheelRoll = 0f;

    public int Gear
    {
        get
        {
            if (SpeedKmh < 78f) return 1;
            if (SpeedKmh < 122f) return 2;
            if (SpeedKmh < 164f) return 3;
            if (SpeedKmh < 204f) return 4;
            if (SpeedKmh < 244f) return 5;
            if (SpeedKmh < 282f) return 6;
            if (SpeedKmh < 316f) return 7;
            return 8;
        }
    }

    public float RpmNormalized
    {
        get
        {
            float[] tops = { 0f, 78f, 122f, 164f, 204f, 244f, 282f, 316f, 360f };
            int g = Gear;
            float lo = tops[g - 1];
            float hi = tops[g];
            return Mathf.Clamp((SpeedKmh - lo) / Mathf.Max(1f, hi - lo), 0.1f, 1.0f);
        }
    }

    public void Initialize(TrackBuilder3D track)
    {
        _track = track;
        BuildCar3D();
        ResetCar();
    }

    public void ToggleCamera()
    {
        IsCockpitCamera = !IsCockpitCamera;
        _cockpitCam.Current = IsCockpitCamera;
        _tCam.Current = !IsCockpitCamera;
    }

    public void ResetCar()
    {
        TrackDistance = 2.0f;
        LateralOffset = 0f;
        HeadingOffset = 0f;
        SpeedKmh = 0f;
        SteerAngle = 0f;
        ErsCharge = 100f;
        ErsEnabled = false;
        CurrentLap = 1;
        CurrentLapTime = 0f;
        ApplyTransform();
    }

    private void BuildCar3D()
    {
        var paintMat = ProceduralMaterialFactory.CreateCarPaintMaterial(new Color(0.88f, 0.91f, 0.96f));
        var blueAccent = ProceduralMaterialFactory.CreateCarPaintMaterial(new Color(0.08f, 0.18f, 0.44f));
        var carbonMat = ProceduralMaterialFactory.CreateCarbonMaterial();
        var rubberMat = ProceduralMaterialFactory.CreateTireRubberMaterial();
        var redRingMat = new StandardMaterial3D { AlbedoColor = new Color(0.92f, 0.08f, 0.08f), Roughness = 0.35f };
        var gloveMat = new StandardMaterial3D { AlbedoColor = new Color(0.09f, 0.34f, 0.86f), Roughness = 0.72f };
        var whiteCuffMat = new StandardMaterial3D { AlbedoColor = new Color(0.94f, 0.96f, 0.99f), Roughness = 0.80f };

        // 1. Glossy Sculpted 3D Monocoque & Nosecone (pointing toward -Z in Godot!)
        AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(0.66f, 0.40f, 2.35f) },
            Position = new Vector3(0f, 0.42f, -0.55f),
            MaterialOverride = paintMat
        });
        AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(0.42f, 0.24f, 1.55f) },
            Position = new Vector3(0f, 0.34f, -2.25f),
            RotationDegrees = new Vector3(4.5f, 0f, 0f),
            MaterialOverride = paintMat
        });
        // Sculpted Sidepod Shoulders
        foreach (float side in new[] { -1f, 1f })
        {
            AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(0.42f, 0.34f, 1.65f) },
                Position = new Vector3(side * 0.50f, 0.40f, -0.10f),
                MaterialOverride = blueAccent
            });
            // Sidepod Mirror
