    private static Node3D CreateWheel3D(StandardMaterial3D rubber, StandardMaterial3D ring, StandardMaterial3D rim, float radius, float width)
    {
        var wheel = new Node3D();
        wheel.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = radius, BottomRadius = radius, Height = width, RadialSegments = 20 },
            RotationDegrees = new Vector3(0f, 0f, 90f),
            MaterialOverride = rubber
        });
        wheel.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = radius * 0.76f, BottomRadius = radius * 0.76f, Height = width + 0.008f, RadialSegments = 18 },
            RotationDegrees = new Vector3(0f, 0f, 90f),
            MaterialOverride = ring
        });
        wheel.AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = radius * 0.64f, BottomRadius = radius * 0.64f, Height = width + 0.014f, RadialSegments = 16 },
            RotationDegrees = new Vector3(0f, 0f, 90f),
            MaterialOverride = rim
        });
        return wheel;
    }

    public override void _PhysicsProcess(double delta)
    {
        if (_track == null) return;
        float dt = (float)delta;

        // Keyboard fallback (for testing on PC) combined with Mobile Touch inputs
        bool left = InputLeft || Input.IsKeyPressed(Key.Left) || Input.IsKeyPressed(Key.A);
        bool right = InputRight || Input.IsKeyPressed(Key.Right) || Input.IsKeyPressed(Key.D);
        bool gas = InputGas || Input.IsKeyPressed(Key.Up) || Input.IsKeyPressed(Key.W);
        bool brake = InputBrake || Input.IsKeyPressed(Key.Down) || Input.IsKeyPressed(Key.S);

        // ERS Charge & Boost
        bool ersActive = ErsEnabled && ErsCharge > 1f && gas && !brake;
        if (ersActive)
        {
            ErsCharge = Mathf.Max(0f, ErsCharge - 20f * dt);
            if (ErsCharge <= 1f) ErsEnabled = false;
        }
        else
        {
            float regen = brake ? 22f : 6f;
            ErsCharge = Mathf.Min(100f, ErsCharge + regen * dt);
        }

        // Longitudinal F1 Acceleration & Carbon-Ceramic Braking
        float maxSpeed = ersActive ? 355f : 318f;
        bool offTrack = Mathf.Abs(LateralOffset) > TrackBuilder3D.TrackHalfWidth + 0.5f;
        if (gas && !brake)
        {
            float accel = ersActive ? 168f : 122f;
            if (offTrack) accel *= 0.55f;
            SpeedKmh = Mathf.Min(maxSpeed, SpeedKmh + accel * dt);
        }
        else if (brake)
        {
            SpeedKmh = Mathf.Max(0f, SpeedKmh - 210f * dt);
            ErsEnabled = false;
        }
        else
        {
            SpeedKmh = Mathf.Max(0f, SpeedKmh - (36f + SpeedKmh * 0.09f) * dt);
        }

        if (offTrack && SpeedKmh > 130f)
        {
            SpeedKmh = Mathf.Max(130f, SpeedKmh - 55f * dt);
        }

        // Responsive Steering & Curvature Following
        float targetSteer = (right ? 1f : 0f) - (left ? 1f : 0f);
        float steerRate = Mathf.Abs(targetSteer) > 0.01f ? 11.5f : 16.0f;
        SteerAngle = Mathf.Lerp(SteerAngle, targetSteer, 1f - Mathf.Exp(-steerRate * dt));

        TrackSample sample = _track.SampleAtDistance(TrackDistance);
        float vMs = SpeedKmh / 3.6f;
        float speedFactor = Mathf.Clamp(SpeedKmh / 20f, 0f, 1f);
        float manualYawRate = SteerAngle * (1.85f / (1.0f + SpeedKmh * 0.0045f)) * speedFactor;
        float roadYawRate = vMs * sample.Curvature;

        HeadingOffset += (manualYawRate - roadYawRate) * dt;
        if (Mathf.Abs(targetSteer) < 0.01f && Mathf.Abs(sample.Curvature) < 0.004f)
        {
            HeadingOffset *= Mathf.Exp(-6.5f * dt);
        }
        HeadingOffset = Mathf.Clamp(HeadingOffset, -0.58f, 0.58f);

        LateralOffset += vMs * Mathf.Sin(HeadingOffset) * dt;
        float maxLat = TrackBuilder3D.BarrierOffset - 1.15f;
        if (Mathf.Abs(LateralOffset) > maxLat)
        {
            LateralOffset = Mathf.Sign(LateralOffset) * maxLat;
            HeadingOffset *= -0.25f;
            SpeedKmh *= 0.72f;
        }

        float prevDist = TrackDistance;
        TrackDistance += Mathf.Max(0f, vMs * Mathf.Cos(HeadingOffset)) * dt;
        CurrentLapTime += dt;

        if (TrackDistance >= _track.TotalLength)
        {
            TrackDistance -= _track.TotalLength;
            if (CurrentLapTime > 5.0f && CurrentLapTime < BestLapTime)
            {
                BestLapTime = CurrentLapTime;
            }
            CurrentLap++;
            CurrentLapTime = 0f;
        }

        // Animate 3D Steering Wheel, Front Tires & Live MFD Telemetry
        _wheelPivot.RotationDegrees = new Vector3(-16f, 0f, -SteerAngle * 52f);
        _wheelRoll -= vMs * dt * 3.0f;
        _frontLeftWheel.Rotation = new Vector3(_wheelRoll, -SteerAngle * 0.34f, 0f);
        _frontRightWheel.Rotation = new Vector3(_wheelRoll, -SteerAngle * 0.34f, 0f);

        // Dynamic speed FOV punch & subtle lateral G-force camera tilt
        _cockpitCam.Fov = Mathf.Lerp(_cockpitCam.Fov, 72f + (SpeedKmh / 355f) * 11f + (ersActive ? 4f : 0f), 1f - Mathf.Exp(-6f * dt));

        // Update 3D Steering Wheel MFD
        _mfdSpeedLabel.Text = $"{(int)SpeedKmh} KPH";
        _mfdGearLabel.Text = $"{Gear}";
        _mfdLapLabel.Text = $"{CurrentLapTime:00.000}";
        _mfdOvertakeLabel.Text = ersActive ? $"ERS ON {(int)ErsCharge}%" : $"OVERTAKE {(int)ErsCharge}%";
        _mfdOvertakeBar.Scale = new Vector3(Mathf.Clamp(ErsCharge / 100f, 0.02f, 1f), 1f, 1f);
        _overtakeBarMat.AlbedoColor = ersActive ? new Color(0.0f, 0.88f, 1.0f) : new Color(0.95f, 0.78f, 0.12f);
        _overtakeBarMat.Emission = _overtakeBarMat.AlbedoColor;

        ApplyTransform();
    }

    private void ApplyTransform()
    {
        TrackSample s = _track.SampleAtDistance(TrackDistance);
        Position = s.Center + s.Right * LateralOffset + Vector3.Up * 0.05f;
        Basis trackBasis = Basis.LookingAt(s.Forward, Vector3.Up);
        Basis = trackBasis.Rotated(Vector3.Up, -HeadingOffset);
    }
}

