        topLeft.AddChild(_lapLbl);

        var subLbl = CreateLabel("GODOT 4 3D  •  C# .NET 8", 11, new Color(0.45f, 0.90f, 1.0f));
        subLbl.Position = new Vector2(12, 42);
        topLeft.AddChild(subLbl);

        // Top-Right Speed / Gear / RPM Card + Camera & Reset Buttons
