        root.AddChild(topRight);

        var rpmBg = new ColorRect { Color = new Color(0.12f, 0.16f, 0.24f), Position = new Vector2(12, 10), Size = new Vector2(226, 8) };
        topRight.AddChild(rpmBg);
        _rpmFill = new ColorRect { Color = new Color(0.0f, 0.90f, 0.45f), Position = new Vector2(12, 10), Size = new Vector2(40, 8) };
        topRight.AddChild(_rpmFill);

        _speedLbl = CreateLabel("0 KM/H", 26, Colors.White);
        _speedLbl.Position = new Vector2(12, 24);
        topRight.AddChild(_speedLbl);

