        resetBtn.Pressed += () => _car.ResetCar();
        root.AddChild(resetBtn);

        // Bottom-Left Multi-Touch Steering Pads (< and >)
        _btnLeft = CreateControlPad("<", new Vector2(24, -148), new Vector2(138, 124), Control.LayoutPreset.BottomLeft, new Color(0.08f, 0.13f, 0.22f, 0.78f), new Color(0.0f, 0.88f, 1.0f));
        root.AddChild(_btnLeft);

        _btnRight = CreateControlPad(">", new Vector2(178, -148), new Vector2(138, 124), Control.LayoutPreset.BottomLeft, new Color(0.08f, 0.13f, 0.22f, 0.78f), new Color(0.0f, 0.88f, 1.0f));
