using Godot;

namespace ApexGP24;

public partial class MainRaceController : Node3D
{
    public override void _Ready()
    {
        SetupEnvironmentAndSun();

        var track = new TrackBuilder3D { Name = "Circuit3D" };
        AddChild(track);
        track.BuildCircuit();

        var car = new PlayerCar3D { Name = "PlayerCar3D" };
        AddChild(car);
        car.Initialize(track);

        var hud = new TouchHud { Name = "TouchHud" };
        AddChild(hud);
        hud.Initialize(car);
    }

    private void SetupEnvironmentAndSun()
    {
        var sky = new Sky();

        // Automatically uses user-uploaded Poly Haven HDRI if placed at res://assets/textures/sky.hdr!
        if (ResourceLoader.Exists("res://assets/textures/sky.hdr"))
        {
            sky.SkyMaterial = new PanoramaSkyMaterial
            {
                Panorama = GD.Load<Texture2D>("res://assets/textures/sky.hdr")
            };
        }
        else
